/* CastUserSnapshotMapper.insertRsrcMstr */
INSERT INTO PMOWN.${mstrTableNm} (
    ${mstrIdColumnNm}, ${mstrNmColumnNm}, PRCS_STTS_CD, CFMTN_YN, USE_YN,
    FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT
) VALUES (
    #{snapshot.rsrcNo},
    '사용자 시뮬레이션 ' || #{snapshot.smltId},
    '99', 'Y', 'Y',
    #{snapshot.loginUserId}, #{snapshot.loginIpAddr}, CURRENT_TIMESTAMP
)

/* CastUserSnapshotMapper.insertCknctAtrb */ INSERT INTO PMOWN.TN_PM_SMLT_CKNCT_ATRB ( SCHDL_ATRB_GROUP_ID, BLCK_ID, TMNL_ID, CKNCT_ID, ALN_CD, DOM_INTL_SE_CD, CRTR_YMD, CHKN_OPEN_PRNMNT_DT, CHKN_CLOSE_PRNMNT_DT, CHKN_TYPE_CD, CHKN_TYPE_DTL_INFO, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) WITH BOOTH AS (
), OPER_HR AS (
) SELECT #{rsrcNo}, CASE WHEN B.TMNL_ID = 'P03' THEN 'P03CKIN' WHEN NVL(C.DOM_INTL_SE_CD, 'I') = 'I' THEN 'P01CKINInt' ELSE 'P01CKINDom' END, B.TMNL_ID, C.CKNCT_ID, B.ALN_CD, NVL(C.DOM_INTL_SE_CD, 'I'), #{excnYmd}, #{excnYmd} || LPAD(H.OPER_BGNG_HOUR, 2, '0') || '00', #{excnYmd} || LPAD(DECODE(H.OPER_END_HOUR, 24, 23, H.OPER_END_HOUR), 2, '0') || DECODE(H.OPER_END_HOUR, 24, '59', '00'), 'M', B.ALN_CD, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP FROM BOOTH B INNER JOIN OPER_HR H ON H.TMNL_ID = B.TMNL_ID AND H.CHKN_ISL_CD = B.CHKN_ISL_CD INNER JOIN ( SELECT K.TMNL_ID, SUBSTR(K.CKNCT_ID, 1, 1) AS CHKN_ISL_CD, K.CKNCT_ID, K.DOM_INTL_SE_CD, ROW_NUMBER() OVER (PARTITION BY K.TMNL_ID, SUBSTR(K.CKNCT_ID, 1, 1) ORDER BY K.CKNCT_ID) AS BOOTH_NO FROM CAOWN.TN_CA_CKNCT K WHERE K.USE_YN = 'Y' AND K.CKNCT_USE_CRG_APLCN_TYPE_CD IN ('A', 'B') ) C ON C.TMNL_ID = B.TMNL_ID AND C.CHKN_ISL_CD = B.CHKN_ISL_CD AND C.BOOTH_NO = B.BOOTH_NO WHERE B.ALN_CD IS NOT NULL

/* CastUserSnapshotMapper.insertSbdAtrb */ INSERT INTO PMOWN.TN_PM_SMLT_SBD_ATRB ( SCHDL_ATRB_GROUP_ID, BLCK_ID, TMNL_ID, CKNCT_ID, ALN_CD, DOM_INTL_SE_CD, CRTR_YMD, OPER_BGNG_DT, OPER_END_DT, CHKN_TYPE_CD, CHKN_TYPE_DTL_INFO, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) WITH ISL AS (
), OPER_HR AS (
), BOOTH AS (
) SELECT #{rsrcNo}, CASE WHEN I.TMNL_ID = 'P03' THEN 'P03SBD' ELSE 'P01SBD' END, I.TMNL_ID, C.CKNCT_ID, A.ALN_CD, NVL(C.DOM_INTL_SE_CD, 'I'), #{excnYmd}, #{excnYmd} || LPAD(H.OPER_BGNG_HOUR, 2, '0') || '00', #{excnYmd} || LPAD(DECODE(H.OPER_END_HOUR, 24, 23, H.OPER_END_HOUR), 2, '0') || DECODE(H.OPER_END_HOUR, 24, '59', '00'), 'C', SUBSTR(A.ALN_CD_LIST, 1, 200), #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP FROM ISL I INNER JOIN OPER_HR H ON H.TMNL_ID = I.TMNL_ID AND H.CHKN_ISL_CD = I.CHKN_ISL_CD INNER JOIN ( SELECT K.TMNL_ID, SUBSTR(K.CKNCT_ID, 1, 1) AS CHKN_ISL_CD, K.CKNCT_ID, K.DOM_INTL_SE_CD, ROW_NUMBER() OVER (PARTITION BY K.TMNL_ID, SUBSTR(K.CKNCT_ID, 1, 1) ORDER BY K.CKNCT_ID) AS DEVICE_NO FROM CAOWN.TN_CA_CKNCT K WHERE K.USE_YN = 'Y' AND K.CKNCT_USE_CRG_APLCN_TYPE_CD = 'H' ) C ON C.TMNL_ID = I.TMNL_ID AND C.CHKN_ISL_CD = I.CHKN_ISL_CD AND C.DEVICE_NO <= NVL(I.SBD_CNT, 0) LEFT OUTER JOIN ( SELECT TMNL_ID, CHKN_ISL_CD, MIN(ALN_CD) AS ALN_CD, LISTAGG(ALN_CD, ',') WITHIN GROUP (ORDER BY ALN_CD) AS ALN_CD_LIST FROM ( SELECT DISTINCT TMNL_ID, CHKN_ISL_CD, ALN_CD FROM BOOTH WHERE ALN_CD IS NOT NULL ) GROUP BY TMNL_ID, CHKN_ISL_CD ) A ON A.TMNL_ID = I.TMNL_ID AND A.CHKN_ISL_CD = I.CHKN_ISL_CD

/* CastUserSnapshotMapper.insertSbdAtrbKiosk */ INSERT INTO PMOWN.TN_PM_SMLT_SBD_ATRB ( SCHDL_ATRB_GROUP_ID, BLCK_ID, TMNL_ID, CKNCT_ID, ALN_CD, DOM_INTL_SE_CD, CRTR_YMD, OPER_BGNG_DT, OPER_END_DT, CHKN_TYPE_CD, CHKN_TYPE_DTL_INFO, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) WITH ISL AS (
), OPER_HR AS (
) SELECT #{rsrcNo}, CASE WHEN I.TMNL_ID = 'P03' THEN 'P03Self' ELSE 'P01Self' END, I.TMNL_ID, C.SLF_CHKN_ISTR_ID, C.ALN_CD, 'I', #{excnYmd}, #{excnYmd} || LPAD(H.OPER_BGNG_HOUR, 2, '0') || '00', #{excnYmd} || LPAD(DECODE(H.OPER_END_HOUR, 24, 23, H.OPER_END_HOUR), 2, '0') || DECODE(H.OPER_END_HOUR, 24, '59', '00'), 'C', SUBSTR(C.ALN_CD_LIST, 1, 200), #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP FROM ISL I INNER JOIN OPER_HR H ON H.TMNL_ID = I.TMNL_ID AND H.CHKN_ISL_CD = I.CHKN_ISL_CD INNER JOIN ( SELECT P.TMNL_ID, SUBSTR(P.SLF_CHKN_ISTR_ID, 1, 1) AS CHKN_ISL_CD, P.SLF_CHKN_ISTR_ID, MIN(P.ALN_CD) AS ALN_CD, LISTAGG(P.ALN_CD, ',') WITHIN GROUP (ORDER BY P.ALN_CD) AS ALN_CD_LIST, ROW_NUMBER() OVER (PARTITION BY P.TMNL_ID, SUBSTR(P.SLF_CHKN_ISTR_ID, 1, 1) ORDER BY P.SLF_CHKN_ISTR_ID) AS DEVICE_NO FROM PMOWN.TN_PM_SLF_CHKN_OPER_PLCY P WHERE #{excnYmd} BETWEEN P.PLCY_BGNG_YMD AND P.PLCY_END_YMD GROUP BY P.TMNL_ID, SUBSTR(P.SLF_CHKN_ISTR_ID, 1, 1), P.SLF_CHKN_ISTR_ID ) C ON C.TMNL_ID = I.TMNL_ID AND C.CHKN_ISL_CD = I.CHKN_ISL_CD AND C.DEVICE_NO <= NVL(I.KOS_CNT, 0)

/* CastUserSnapshotMapper.insertDptgtAtrb */ INSERT INTO PMOWN.TN_PM_SMLT_FCLTY_OPNG_DPTGT_ATRB ( DPTGT_ATRB_ID, FCLTY_OPNG_SN, TMNL_ID, FCLT_SE_CD, GATE_NO, FCLTY_CNT, OPER_BGNG_HM, OPER_END_HM, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) WITH DPTGT AS (
), OPER_HR AS (
) SELECT #{rsrcNo}, ROW_NUMBER() OVER (ORDER BY D.TMNL_ID, D.DPTGT_NO, H.OPER_HR_SN), D.TMNL_ID, 'D', D.DPTGT_NO, NVL(D.GNRL_SRCH_CNTOM, 0) + NVL(D.SMART_PASS_SRCH_CNTOM, 0), LPAD(H.OPER_BGNG_HOUR, 2, '0') || '00', LPAD(DECODE(H.OPER_END_HOUR, 24, 23, H.OPER_END_HOUR), 2, '0') || DECODE(H.OPER_END_HOUR, 24, '59', '00'), #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP FROM DPTGT D INNER JOIN OPER_HR H ON H.TMNL_ID = D.TMNL_ID AND H.DPTGT_NO = D.DPTGT_NO WHERE D.OPER_YN = 'Y'
